import { registerWebComponents } from '@domg-wc/common';
import { VlSelectRichComponent } from '@domg-wc/components/form';

registerWebComponents([VlSelectRichComponent]);

const select = document.querySelector('#geboorteplaats');
// Geef een nieuwe array mee om de opties te wijzigen, zonder de huidige te wijzigen: vl-select-rich vergelijkt de
// inhoud van de oude en de nieuwe array.
select.options = [
    { label: 'Hasselt', value: 'hasselt' },
    { label: 'Turnhout', value: 'turnhout' },
    { label: 'Knokke-Heist', value: 'knokke-heist' },
    { label: 'Waregem', value: 'waregem' },
    { label: 'Lier', value: 'lier' },
    { label: 'Rio Piedras', value: 'rio piedras' },
];

// event.detail.value is de value van de gekozen optie, of null zonder keuze; select.getSelected() geeft hetzelfde.
select.addEventListener('vl-change', (event) => {
    console.log(event.detail.value);
});

